body {
  background-color: #f5f6f8;
  color: #18181b;
  font-family: system-ui, "Segoe UI", sans-serif;
  line-height: 1.6;
  padding: 16px;
}

h1 { font-size: 26px; }

#output {
  list-style: none;
  padding: 0;
  max-width: 520px;
}

#output li {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
  background-color: #ffffff;
  border-radius: 8px;
  padding: 10px 14px;
  margin-bottom: 8px;
}

#output span { color: #3f3f46; font-size: 14px; }

#output code {
  font-family: ui-monospace, "Cascadia Mono", monospace;
  font-weight: 700;
  color: #1d4ed8;
}

// Shop.mn — TypeScript.
// Preview нь төрлийг хуулаад ажиллуулна; «Шалгах» дарахад ЖИНХЭНЭ TypeScript
// хөрвүүлэгч төрлүүдийг чинь шалгана.

// энд бичнэ үү
function describeAction(action) {
  return action.kind;
}

// Tier 1-д модуль байхгүй тул функцүүдээ ил гаргана.
(globalThis as unknown as Record<string, unknown>).SHOP = { describeAction };

// Үр дүнг харуулах жижиг самбар. Энэ файлыг өөрчлөх шаардлагагүй.

const output = document.getElementById("output");

function row(label, value) {
  const line = document.createElement("li");
  const name = document.createElement("span");
  name.textContent = label;
  const result = document.createElement("code");
  result.textContent = value;
  line.append(name, result);
  output.append(line);
}

(function () {
  const shop = window.SHOP || {};
  window.OUT = {};

  const actions = [
    { kind: "add", name: "Монгол дээл", price: 129000 },
    { kind: "remove", id: 2 },
    { kind: "clear" },
  ];

  try {
    if (typeof shop.describeAction === "function") {
      window.OUT.descriptions = actions.map(shop.describeAction);
      window.OUT.addText = window.OUT.descriptions[0];
      window.OUT.removeText = window.OUT.descriptions[1];
      window.OUT.clearText = window.OUT.descriptions[2];
      row('describeAction({ kind: "add" })', window.OUT.addText);
      row('describeAction({ kind: "remove" })', window.OUT.removeText);
      row('describeAction({ kind: "clear" })', window.OUT.clearText);
    }
  } catch (problem) {
    row("алдаа", problem.message);
  }

  document.body.dataset.ready = "1";
})();

