// Shop.mn — TypeScript.
// Preview нь төрлийг хуулаад ажиллуулна; «Шалгах» дарахад ЖИНХЭНЭ TypeScript
// хөрвүүлэгч төрлүүдийг чинь шалгана.

type CartAction =
  | { kind: "add"; name: string; price: number }
  | { kind: "remove"; id: number }
  | { kind: "clear" };

function describeAction(action: CartAction): string {
  switch (action.kind) {
    case "add":
      return `Нэмэв: ${action.name}`;
    case "remove":
      return `Хаслаа: #${action.id}`;
    case "clear":
      return "Сагс цэвэрлэв";
    default: {
      const _exhaustive: never = action;
      return _exhaustive;
    }
  }
}

// Tier 1-д модуль байхгүй тул функцүүдээ ил гаргана.
(globalThis as unknown as Record<string, unknown>).SHOP = { describeAction };
